from __future__ import annotations
from datetime import datetime,timezone
def build_report(analysis):
    md=analysis.get("metadata",{})
    return {"title":"GeoAnomaly Pro — Scientific Geospatial Anomaly Analysis","generated_at":datetime.now(timezone.utc).isoformat(),"scientific_boundary":"GeoAnomaly Pro identifies statistically unusual surface geospatial signatures worthy of field investigation. It does not directly detect buried objects, depth, gold, graves, rooms, wells or tunnels from satellite imagery alone.","methodology":["Sentinel-2 SR Harmonized real observations","SRTM DEM terrain features","Sentinel-2 NDVI, NDMI, NDWI and NDBI","Iron-oxide and clay spectral proxies (20 m source bands)","Dynamic World 10 m land-cover probabilities","Per-cell historical surface comparison","Robust Z-score","Isolation Forest","Local Outlier Factor (LOF)","Surface-context/artifact suppression","Multi-scale spatial consensus","Landsat 8/9 thermal context at 30 m","Evidence fusion and target ranking"],"metadata":md,"datasets":analysis.get("datasets",[]),"targets":analysis.get("targets",[]),"score_trace_policy":"Each target carries an immutable trace_id and the exact component values/weights used to derive its final evidence score.","quality":analysis.get("quality",{}),"limitations":["Strength percentages are ranking scores, not probabilities of a buried object.","Surface length/width estimate the observed anomalous footprint, not underground dimensions.","Depth is not estimated from the current satellite-only pipeline.","Iron/clay ratios are spectral proxies and are not direct identification of gold.","Dynamic World and spectral change are contextual evidence, not proof of human intervention or age.","Field/geophysical verification is required before subsurface conclusions."]}
